def intervalSum (a b : Fin 20) : Rat := ∑ n in Finset.Icc (a.val + 2) (b.val + 2), (n + 1 : Rat)⁻¹

def validInterval (a b : Fin 20) : Bool := decide (a.val + 2 < b.val + 2)

def integerSum (xs : List (Fin 20 × Fin 20)) : Bool := decide ((xs.map (fun p => intervalSum p.1 p.2)).sum.den = 1)

def v2 (n : Nat) : Nat := if n = 0 then 0 else Nat.trailingZeros n

def maxV2CountEven (xs : List (Fin 20 × Fin 20)) : Bool := decide (Even ((xs.filter (fun p => v2 (p.1.val + 2) = xs.foldl (fun m q => max m (v2 (q.1.val + 2))) 0) xs).length))

def check_fragment : Bool := ∀ xs : List (Fin 20 × Fin 20), xs.length ≤ 3 → (∀ p ∈ xs, validInterval p.1 p.2) → integerSum xs = true → maxV2CountEven xs

